"use client";

// Ph — thin typed wrapper over @iconify/react for Phosphor line icons (the
// "Aurora Glass v3" UI-chrome icon layer: arrows, markers, list glyphs).
//
// OFFLINE: the Phosphor icons are registered once at module scope from bundled
// data, so rendering never hits the Iconify network API (Next 16 Turbopack
// can't run the unplugin-icons webpack path, so this is the reliable route).
// `ssr` renders the SVG on the server pass too — the data is local, so there
// is no hydration flash.
//
// SUBSET ONLY: ph-subset.json holds just the names the site uses (generated by
// scripts/ph-subset.mjs). The full @iconify-json/ph collection was 4.4 MB of
// JS — 953 KB over the wire — on every page, parsed before hydration. A new
// <Ph name> must be added to that script and the JSON regenerated; otherwise
// it still renders, but via a runtime fetch from the Iconify API.

import { Icon, addCollection, type IconifyJSON } from "@iconify/react";
import phIcons from "./ph-subset.json";

// Register the offline subset once per bundle; every <Ph/> resolves its
// "ph:*" name from this in-memory data.
addCollection(phIcons as IconifyJSON);

/** Phosphor weights — encoded as a name suffix in the ph collection. */
export type PhWeight = "thin" | "light" | "regular" | "bold" | "fill" | "duotone";

export interface PhProps {
  /** Phosphor icon name WITHOUT the "ph:" prefix, e.g. "arrow-up-right". */
  name: string;
  /** Square size in px. Default 18. */
  size?: number;
  /** Stroke weight variant (suffix on the icon name). Default "regular". */
  weight?: PhWeight;
  className?: string;
}

export function Ph({
  name,
  size = 18,
  weight = "regular",
  className,
}: PhProps) {
  // "regular" is the unsuffixed base name; other weights append "-<weight>".
  const icon = weight === "regular" ? `ph:${name}` : `ph:${name}-${weight}`;
  return (
    <Icon
      icon={icon}
      width={size}
      height={size}
      className={className}
      aria-hidden="true"
      ssr
    />
  );
}

export default Ph;
